class Solution {
public:
    int stoneGameII(vector<int>& piles) {
        int n = piles.size();
        vector<int> suffix(n + 1, 0);
        for (int i = n - 1; i >= 0; i--)
            suffix[i] = suffix[i + 1] + piles[i];

        // dp[i][m] = max stones the current player collects from piles[i:] with M = m
        vector<vector<int>> dp(n + 1, vector<int>(n + 2, 0));

        for (int i = n - 1; i >= 0; i--) {
            for (int m = 1; m <= n; m++) {
                int minOpp = INT_MAX;
                for (int x = 1; x <= 2 * m; x++) {
                    int ni = i + x;
                    if (ni >= n) {
                        minOpp = 0;
                        break;
                    }
                    int nm = max(m, x);
                    if (nm > n) nm = n;
                    minOpp = min(minOpp, dp[ni][nm]);
                }
                dp[i][m] = suffix[i] - minOpp;
            }
        }
        return dp[0][1];
    }
};
